package com.yuvro.todo.controller;

import com.yuvro.todo.entity.Task;
import com.yuvro.todo.entity.User;
import com.yuvro.todo.repository.TaskRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

import java.util.*;
import java.util.stream.Collectors;

@RestController
@RequestMapping("/api/tasks")
public class TaskController {

    private final TaskRepository taskRepository;

    public TaskController(TaskRepository taskRepository) {
        this.taskRepository = taskRepository;
    }

    private User getAuthenticatedUser(Authentication authentication) {
        if (authentication != null && authentication.getPrincipal() instanceof User user) {
            return user;
        }
        return null;
    }

    @PostMapping
    public ResponseEntity<Map<String, Object>> createTask(
            Authentication authentication,
            @RequestBody(required = false) Map<String, Object> body) {
        User currentUser = getAuthenticatedUser(authentication);
        if (currentUser == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Collections.singletonMap("error", "Authorization token is missing or invalid"));
        }

        if (body == null || !body.containsKey("title")) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Collections.singletonMap("error", "Title is required"));
        }

        String title = body.get("title") != null ? body.get("title").toString().trim() : "";
        if (title.isEmpty()) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Collections.singletonMap("error", "Title is required"));
        }

        String description = body.get("description") != null ? body.get("description").toString() : "";

        Task task = new Task(currentUser, title, description);
        task = taskRepository.save(task);

        Map<String, Object> response = new HashMap<>();
        response.put("message", "Task created successfully");
        response.put("task", task.toDict());
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    @GetMapping
    public ResponseEntity<Map<String, Object>> listTasks(Authentication authentication) {
        User currentUser = getAuthenticatedUser(authentication);
        if (currentUser == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Collections.singletonMap("error", "Authorization token is missing or invalid"));
        }

        List<Task> tasks = taskRepository.findByUserIdOrderByCreatedAtDesc(currentUser.getId());
        List<Map<String, Object>> taskDicts = tasks.stream()
                .map(Task::toDict)
                .collect(Collectors.toList());

        return ResponseEntity.ok(Collections.singletonMap("tasks", taskDicts));
    }

    @GetMapping("/{id}")
    public ResponseEntity<Map<String, Object>> getTask(
            Authentication authentication,
            @PathVariable Long id) {
        User currentUser = getAuthenticatedUser(authentication);
        if (currentUser == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Collections.singletonMap("error", "Authorization token is missing or invalid"));
        }

        Optional<Task> taskOpt = taskRepository.findByIdAndUserId(id, currentUser.getId());
        if (taskOpt.isEmpty()) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(Collections.singletonMap("error", "Task not found"));
        }

        return ResponseEntity.ok(Collections.singletonMap("task", taskOpt.get().toDict()));
    }

    @RequestMapping(value = "/{id}", method = {RequestMethod.PUT, RequestMethod.PATCH})
    public ResponseEntity<Map<String, Object>> updateTask(
            Authentication authentication,
            @PathVariable Long id,
            @RequestBody(required = false) Map<String, Object> body) {
        User currentUser = getAuthenticatedUser(authentication);
        if (currentUser == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Collections.singletonMap("error", "Authorization token is missing or invalid"));
        }

        Optional<Task> taskOpt = taskRepository.findByIdAndUserId(id, currentUser.getId());
        if (taskOpt.isEmpty()) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(Collections.singletonMap("error", "Task not found"));
        }

        Task task = taskOpt.get();
        if (body != null) {
            if (body.containsKey("title")) {
                String title = body.get("title") != null ? body.get("title").toString().trim() : "";
                if (title.isEmpty()) {
                    return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                            .body(Collections.singletonMap("error", "Title cannot be empty"));
                }
                task.setTitle(title);
            }

            if (body.containsKey("description")) {
                task.setDescription(body.get("description") != null ? body.get("description").toString() : null);
            }

            if (body.containsKey("is_completed")) {
                Object comp = body.get("is_completed");
                if (comp instanceof Boolean b) {
                    task.setIsCompleted(b);
                } else if (comp != null) {
                    task.setIsCompleted(Boolean.parseBoolean(comp.toString()));
                }
            }
        }

        task = taskRepository.save(task);

        Map<String, Object> response = new HashMap<>();
        response.put("message", "Task updated successfully");
        response.put("task", task.toDict());
        return ResponseEntity.ok(response);
    }
}

